from lib import *
S = SS('h26')
steps = [
    step("PerRPCCredentials(每次调用附带令牌的接口:GetRequestMetadata 返回要加的头,RequireTransportSecurity 声明是否必须加密传输)。声明需要加密(true)却配了明文连接:grpc.NewClient 直接返回错误“grpc: the credentials require transport level security (use grpc.WithTransportCredentials() to set)”;声明不需要(false)配明文连接:能用,但代理(相当于线路上的窃听者)在线上直接看到 “authorization: Bearer SECRET-TOKEN-123”;声明需要加密、配了 TLS:NewClient 成功,调用成功。令牌一般都应该声明需要加密传输,别为了方便设成 false。", t=tl(S(1)), done=lidx(S(1), 'TLS 连接'), mark=lidx(S(1), 'RequireTransportSecurity()=false'), b=bars([['需要加密 + 明文:令牌泄露', 0, '被 NewClient 拒绝'], ['声明不需要 + 明文:线上看到令牌', 1, '明文可见']], 1.2, mark=[1], done=[0]), kv=KV([['true + 明文', 'NewClient 报错'], ['false + 明文', '令牌在线上是明文'], ['true + TLS', '正常']], ['false + 明文'])),
    step("GetRequestMetadata 每个 RPC 调用一次:100 个调用共 100 次。令牌每次都在线上,但因为 HTTP/2 的头压缩(HPACK 动态表),1000 字节的令牌只有第一个请求要完整发送:请求 HEADERS 帧载荷大小,第 1 个 716 字节,第 2 个 17 字节,第 100 个 9 字节。所以每个请求带令牌的线上代价很小;但 GetRequestMetadata 在每个调用的关键路径上,里面的实现要快(缓存令牌),不能每次都去网络取。", t=tl(S(2)), done=lidx(S(2), '100 个调用'), mark=lidx(S(2), '100 个调用'), b=bars([['第 1 个请求 HEADERS 载荷(字节)', 716, '716'], ['第 2 个', 17, '17'], ['第 100 个', 9, '9']], 750, mark=[0], done=[1, 2]), kv=KV([['GetRequestMetadata', '每个 RPC 调用一次(100 次)'], ['第 1 个请求头', '716 字节(含令牌)'], ['之后', '9~17 字节(HPACK)']], ['之后'])),
    step("令牌 1 秒过期,服务端时钟比客户端快 100 ms(模拟时钟偏差/传输延迟),3 秒内每 20 ms 调用一次(约 141 次):每次都取新令牌:取令牌 141 次,被拒 0 次——最安全但代价最大;缓存、过期才刷新:取令牌 3 次,被服务端拒绝 13 次(9.2%)——客户端以为令牌还有效,服务端已经认为过期;缓存并提前 300 ms 刷新:取令牌 5 次,被拒 0 次。刷新要比过期提前一个“时钟偏差 + 传输延迟”的余量;具体提前多少要看你的环境(别的库的默认值本篇没有验证)。", t=tl(S(3)), done=lidx(S(3), '提前 300 ms 刷新'), mark=lidx(S(3), '缓存,过期才刷新'), b=bars([['每次取新令牌:取令牌次数', 141, '141'], ['缓存提前刷新:取令牌次数', 5, '5'], ['缓存过期才刷新:被拒次数', 13, '13']], 150, mark=[2], done=[0, 1]), kv=KV([['每次取新令牌', '141 次取,0 次被拒'], ['缓存,过期才刷新', '3 次取,13 次被拒(9.2%)'], ['缓存,提前 300 ms 刷新', '5 次取,0 次被拒']], ['缓存,提前 300 ms 刷新'])),
    step("令牌刚过期、50 个并发调用同时需要新令牌,取一次令牌要 100 ms:取令牌的函数不加锁,50 个调用各自去取,共取 50 次;加锁(只有一个去取、其余等它的结果),只取 1 次。没有保护的刷新会在令牌过期的瞬间把令牌服务打一波“惊群”。自己写的实现要自己加这个保护(现成的 TokenSource 库是否内置,本篇没有查)。", t=tl(S(4)), done=lidx(S(4), '加锁'), mark=lidx(S(4), '不加锁'), b=bars([['不加锁:取令牌次数', 50, '50'], ['加锁:取令牌次数', 1, '1']], 55, mark=[0], done=[1]), kv=KV([['不加锁', '50 个并发 = 取 50 次'], ['加锁', '取 1 次,其余等待'], ['原因', 'GetRequestMetadata 会被并发调用']], ['加锁'])),
    step("取令牌失败或很慢时:GetRequestMetadata 返回普通 error:调用 code=Unauthenticated,message=“transport: per-RPC creds failed due to error: 取令牌失败”;返回 status.Error(Unavailable, …):调用的 code 就是 Unavailable,message 原样;返回 PermissionDenied 同理。所以如果想让调用方能重试(比如令牌服务暂时不可用),要返回 status 错误并选对 code,不要返回普通 error。取令牌要 500 ms、调用 deadline 200 ms:取令牌的 ctx 跟着调用的 deadline,201.2 ms 后返回,Unauthenticated“… context deadline exceeded”——取令牌的时间算在调用的 deadline 里。", t=tl(S(5)), done=lidx(S(5), '取令牌要 500 ms'), mark=lidx(S(5), '普通 error'), b=bars([['deadline 200 ms,取令牌 500 ms:返回用时 ms', 201.2, '201.2']], 210, done=[0]), kv=KV([['普通 error', '变成 Unauthenticated'], ['status 错误', 'code 原样(Unavailable 可以重试)'], ['取令牌慢', '占用调用的 deadline']], ['status 错误'])),
    step("连接级的凭证(WithPerRPCCredentials)和单次调用的凭证(grpc.PerRPCCredentials 调用选项)同时存在:只有连接级时,服务端看到 authorization = [“Bearer CONN-LEVEL”];再加单次调用的凭证,服务端看到的是两个值 [“Bearer CONN-LEVEL” “Bearer CALL-LEVEL”]——不是覆盖,是都发。如果想“某次调用换一个身份”,不能指望单次凭证覆盖连接级的,要把连接级的拿掉、或在服务端明确取哪个。", t=tl(S(6)), done=lidx(S(6), '再加单次调用的凭证'), mark=lidx(S(6), '只有连接级凭证'), b=bars([['只有连接级:服务端看到的 authorization 个数', 1, '1'], ['再加单次凭证:个数', 2, '2']], 3, mark=[0], done=[1]), kv=KV([['连接级', 'Bearer CONN-LEVEL'], ['再加单次调用的', '两个值都发给服务端'], ['含义', '不是覆盖']], ['含义'])),
]
A = mkarth('h26', 26, 'gRPC,认证,PerRPCCredentials,token,令牌刷新,惊群,RequireTransportSecurity,Go,真实验证,动画演示',
    '实测 gRPC 的 per-RPC credentials:声明需要加密时明文连接会被拒绝,声明不需要时令牌在线上是明文;每个请求调用一次、HPACK 让重复令牌只剩几个字节;令牌过期前不提前刷新会被拒 9.2%;并发刷新不加锁会取 50 次;错误码的映射;连接级与单次凭证是叠加。',
    'gRPC 的 token 认证是怎么挂到每个调用上的?为什么必须配 TLS?token 要过期了怎么刷新才不出错?并发刷新会不会把令牌服务打爆?这篇用自己实现的 PerRPCCredentials 逐项验证。',
    [('9.2% → 0%', '令牌过期才刷新时被服务端拒绝的比例;提前 300 ms 刷新后为 0'), ('50 → 1', '50 个并发调用遇到过期令牌,不加锁与加锁时取令牌的次数'), ('716 → 9 字节', '1000 字节令牌的请求 HEADERS 帧,第 1 个与第 100 个的大小')],
    [('接口', '<p>PerRPCCredentials 有两个方法:GetRequestMetadata(每个 RPC 调用一次,返回要加的头)和 RequireTransportSecurity(是否必须加密)。用 WithPerRPCCredentials 设为连接级,或用 PerRPCCredentials 调用选项设单次。</p>'),
     ('必须加密', '<p>声明需要加密而连接是明文,NewClient 直接报错;如果声明不需要,令牌会在线上以明文出现。</p>'),
     ('刷新要提前', '<p>令牌过期前就刷新,留出时钟偏差和传输延迟的余量,否则会出现一批“刚好过期”的请求被拒绝。</p>'),
     ('并发保护', '<p>GetRequestMetadata 会被并发调用,刷新令牌要有锁,避免过期瞬间所有调用一起去取。</p>'),
     ('错误和 deadline', '<p>返回 status 错误能控制调用得到的 code;返回普通 error 会变成 Unauthenticated。取令牌的时间算在调用的 deadline 里。</p>'),
     ('叠加而非覆盖', '<p>连接级和单次调用的凭证同时存在时,两个 authorization 都会被发送。</p>')],
    steps,
    [ENV_H + '。令牌与过期校验是我自己写的最小实现(不是 OAuth);“服务端时钟快 100 ms”是人为模拟,用来说明提前刷新的必要性,实际余量要看你的时钟偏差和网络延迟;HEADERS 帧大小来自抓包代理;TLS 部分用内存里生成的 CA',
     '没有验证:官方 oauth / google 凭证包的刷新策略与默认提前量;credentials.PerRPCCredentials 在 xDS / ALTS 下的行为;令牌被服务端拒绝(Unauthenticated)后客户端是否要强制刷新再重试;服务端从 metadata 读令牌后对 authorization 多值的取舍;JWT 校验的性能'],
    '认证')
